WITH seed_users AS (
  SELECT * FROM ( VALUES
    ('00000000-0000-4000-8000-000000000001'::uuid, 'user@example.com', 'Password123!', '{"provider":"email","providers":["email"]}'::jsonb),
    ('00000000-0000-4000-8000-000000000002'::uuid, 'admin@example.com', 'Admin123!', '{"provider":"email","providers":["email"],"role":"Admin"}'::jsonb),
    ('a3b3cf93-6956-41c7-bec0-13f95dd42f26'::uuid, 'lukasz@example.com', 'Password123!', '{"provider":"email","providers":["email"],"role":"Admin"}'::jsonb)
  ) AS t(id, email, plain_pw, app_meta)
)
INSERT INTO auth.users (
  id, instance_id, aud, role, email, encrypted_password, email_confirmed_at,
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
  confirmation_token, email_change, email_change_token_new, recovery_token
)
SELECT
  id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
  email, crypt(plain_pw, gen_salt('bf')), now(), app_meta, '{}'::jsonb, now(), now(),
  '', '', '', ''
FROM seed_users
  ON CONFLICT (id) DO NOTHING;

INSERT INTO auth.identities (
  id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at
)
SELECT
  gen_random_uuid(), u.id, u.id, 'email',
  json_build_object('sub', u.id, 'email', u.email), now(), now(), now()
FROM auth.users u
  ON CONFLICT (provider_id, provider) DO NOTHING;

