&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="hljs-variable language_">this</span>.<span class="hljs-title function_">closePopup</span>(status);
&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});
