&nbsp;&nbsp;}
&nbsp;&nbsp;<span class="hljs-title function_">acceptCookies</span>(<span class="hljs-params"></span>) {
&nbsp;&nbsp;&nbsp;&nbsp;<span class="hljs-variable language_">localStorage</span>.<span class="hljs-title function_">setItem</span>(<span class="hljs-title class_">LocalStorageEnum</span>.<span class="hljs-property">COOKIES_CONSENT</span>, <span class="hljs-string">''true''</span>);
&nbsp;&nbsp;}
&nbsp;&nbsp;<span class="hljs-title function_">denyCookies</span>(<span class="hljs-params"></span>) {
&nbsp;&nbsp;&nbsp;&nbsp;<span class="hljs-variable language_">localStorage</span>.<span class="hljs-title function_">setItem</span>(<span class="hljs-title class_">LocalStorageEnum</span>.<span class="hljs-property">COOKIES_CONSENT</span>, <span class="hljs-string">''false''</span>);
&nbsp;&nbsp;}
&nbsp;&nbsp;<span class="hljs-title function_">closePopup</span>(<span class="hljs-params"><span class="hljs-attr">status</span>: <span class="hljs-title class_">ModalStatusEnum</span></span>) {
