&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="hljs-title function_">orderBy</span>(<span class="hljs-string">''date''</span>, <span class="hljs-title class_">QueryOperators</span>.<span class="hljs-property">DESC</span>));
