  <span class="hljs-attr">styleUrl</span>: <span class="hljs-string">''./add-image.component.scss''</span>,
  <span class="hljs-attr">changeDetection</span>: <span class="hljs-title class_">ChangeDetectionStrategy</span>.<span class="hljs-property">OnPush</span>
})
<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">AddImageComponent</span> {
  form = <span class="hljs-keyword">new</span> <span class="hljs-title class_">FormGroup</span>&lt;<span class="hljs-title class_">AddImageControls</span>&gt;({
    <span class="hljs-attr">src</span>: <span class="hljs-keyword">new</span> <span class="hljs-title class_">FormControl</span>&lt;<span class="hljs-built_in">string</span> | <span class="hljs-literal">null</span>&gt;(<span class="hljs-string">''''</span>),
    <span class="hljs-attr">alt</span>: <span class="hljs-keyword">new</span> <span class="hljs-title class_">FormControl</span>&lt;<span class="hljs-built_in">string</span> | <span class="hljs-literal">null</span>&gt;(<span class="hljs-string">''''</span>),
  })
}

</code></pre><div></div><div></div><pre data-language="xml"><code class="xml"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"dialog-content"</span>&gt;</span>
  <span class="hljs-tag">&lt;<span class="hljs-name">h3</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"text-lg font-medium mb-4"</span>&gt;</span>Insert Image<span class="hljs-tag">&lt;/<span class="hljs-name">h3</span>&gt;</span>
  <span class="hljs-tag">&lt;<span class="hljs-name">form</span> [<span class="hljs-attr">formGroup</span>]=<span class="hljs-string">"form"</span>&gt;</span>
    <span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"mb-4"</span>&gt;</span>
      <span class="hljs-tag">&lt;<span class="hljs-name">label</span> <span class="hljs-attr">for</span>=<span class="hljs-string">"src"</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"block text-sm font-medium"</span>&gt;</span>Image URL<span class="hljs-tag">&lt;/<span class="hljs-name">label</span>&gt;</span>
      <span class="hljs-tag">&lt;<span class="hljs-name">input</span> <span class="hljs-attr">type</span>=<span class="hljs-string">"text"</span> <span class="hljs-attr">id</span>=<span class="hljs-string">"src"</span> <span class="hljs-attr">formControlName</span>=<span class="hljs-string">"src"</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"input input-bordered w-full"</span>
        <span class="hljs-attr">placeholder</span>=<span class="hljs-string">"https://example.com/image.jpg"</span> /&gt;</span>
    <span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>
    <span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"mb-4"</span>&gt;</span>
      <span class="hljs-tag">&lt;<span class="hljs-name">label</span> <span class="hljs-attr">for</span>=<span class="hljs-string">"alt"</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"block text-sm font-medium"</span>&gt;</span>Alt Text<span class="hljs-tag">&lt;/<span class="hljs-name">label</span>&gt;</span>
      <span class="hljs-tag">&lt;<span class="hljs-name">input</span> <span class="hljs-attr">type</span>=<span class="hljs-string">"text"</span> <span class="hljs-attr">id</span>=<span class="hljs-string">"alt"</span> <span class="hljs-attr">formControlName</span>=<span class="hljs-string">"alt"</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"input input-bordered w-full"</span>
        <span class="hljs-attr">placeholder</span>=<span class="hljs-string">"Description of the image"</span> /&gt;</span>
    <span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>
  <span class="hljs-tag">&lt;/<span class="hljs-name">form</span>&gt;</span>
<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>
</code></pre><h3 class="ql-align-center">Insert &lt;img&gt; tag</h3><div>Inside <strong>add-post.component.ts</strong>, we need to refactor injecting dynamic dialog:</div><div></div><pre data-language="typescript"><code class="typescript">dialogService = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">DynamicDialogService</span>&lt;<span class="hljs-title class_">AddImageForm</span>&gt;);
</code></pre><div>As you can see, we pass <strong>AddImageForm</strong> type in DI, when injection service. So it''s given us strong typed from on subscribe here:</div><div></div><pre data-language="typescript"><code class="typescript"><span class="hljs-title function_">insertImage</span>(<span class="hljs-params"></span>) {
  <span class="hljs-keyword">const</span> <span class="hljs-attr">modalConfig</span>: <span class="hljs-title class_">ModalConfig</span> = {
    <span class="hljs-attr">title</span>: <span class="hljs-string">''Add Image''</span>,
    <span class="hljs-attr">primaryButton</span>: <span class="hljs-string">''Insert''</span>,
    <span class="hljs-attr">secondaryButton</span>: <span class="hljs-string">''Cancel''</span>,
  }
  <span class="hljs-variable language_">this</span>.<span class="hljs-property">range</span> = <span class="hljs-variable language_">this</span>.<span class="hljs-title function_">quill</span>().<span class="hljs-property">quillEditor</span>.<span class="hljs-title function_">getSelection</span>();
  <span class="hljs-variable language_">this</span>.<span class="hljs-property">dialogService</span>.<span class="hljs-property">openDialog</span>&lt;<span class="hljs-title class_">AddImageComponent</span>&gt;
    (<span class="hljs-variable language_">this</span>.<span class="hljs-property">viewContainerRef</span>, modalConfig, <span class="hljs-title class_">AddImageComponent</span>).<span class="hljs-title function_">subscribe</span>(<span class="hljs-function">(<span class="hljs-params">modalStatus</span>) =&gt;</span> {
      <span class="hljs-keyword">if</span> (modalStatus.<span class="hljs-property">data</span>) {
        <span class="hljs-keyword">const</span> imgTag = <span class="hljs-string">`&lt;img src="<span class="hljs-subst">${modalStatus.data.form.controls.src.value}</span>" alt="Image" style="max-width: 100%;"&gt;`</span>;
        <span class="hljs-keyword">if</span> (<span class="hljs-variable language_">this</span>.<span class="hljs-property">range</span>) {
          <span class="hljs-variable language_">this</span>.<span class="hljs-title function_">quill</span>().<span class="hljs-property">quillEditor</span>.<span class="hljs-property">clipboard</span>.<span class="hljs-title function_">dangerouslyPasteHTML</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-property">range</span>.<span class="hljs-property">index</span>, imgTag); <span class="hljs-comment">// Insert the &lt;img&gt; tag</span>
          <span class="hljs-variable language_">this</span>.<span class="hljs-property">blogForm</span>.<span class="hljs-property">controls</span>.<span class="hljs-property">content</span>.<span class="hljs-title function_">setValue</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-title function_">quill</span>().<span class="hljs-property">quillEditor</span>.<span class="hljs-property">root</span>.<span class="hljs-property">innerHTML</span>); <span class="hljs-comment">// Update the form control</span>
        }
      }
    });
}
</code></pre><div></div><div></div><div></div><div>Of course it should be <span style="color: rgb(206, 145, 120); background-color: rgb(30, 30, 30);">alt="</span><span style="color: rgb(86, 156, 214); background-color: rgb(30, 30, 30);">${</span><span style="color: rgb(156, 220, 254); background-color: rgb(30, 30, 30);">modalStatus</span><span style="color: rgb(212, 212, 212); background-color: rgb(30, 30, 30);">.</span><span style="color: rgb(156, 220, 254); background-color: rgb(30, 30, 30);">data</span><span style="color: rgb(212, 212, 212); background-color: rgb(30, 30, 30);">.</span><span style="color: rgb(156, 220, 254); background-color: rgb(30, 30, 30);">form</span><span style="color: rgb(212, 212, 212); background-color: rgb(30, 30, 30);">.</span><span style="color: rgb(156, 220, 254); background-color: rgb(30, 30, 30);">controls</span><span style="color: rgb(212, 212, 212); background-color: rgb(30, 30, 30);">.</span><span style="color: rgb(156, 220, 254); background-color: rgb(30, 30, 30);">alt</span><span style="color: rgb(86, 156, 214); background-color: rgb(30, 30, 30);">}</span><span style="color: rgb(206, 145, 120); background-color: rgb(30, 30, 30);">" </span></div><div>I had a really headache, I added this code and appfroze; the whole code become unformatted. The app was crashing, and I was concerned that I would need to perform some performance optimization XD. No please, I''m just JS, I don''t know algorithms. Hopefully I switch from Chrome to Safari, and all working fine, Surely I need to do code optimization for that. issue is that manually highlighting consumes a lot of resources, as does putting images needed every time to set control value. Ehh, I need some algorithm that will put images all at once at save, but need to calculate &lt;img&gt; length. Also, when I insert one image, next place to put will shift.</div><div>But we''ll achieve everything, just one little step after another.</div><h3 class="ql-align-center">Highlight html refactor</h3><div>I refactored the HTML section after saving; I''m not query all Highlight blocks, only this ones, which are HTML/XML or TS, <strong>querySelectorAll(''pre[data-language="xml"]'')</strong>:</div><div></div><pre data-language="typescript"><code class="typescript"><span class="hljs-title function_">extractAndHighlight</span>(<span class="hljs-attr">htmlContent</span>: <span class="hljs-built_in">string</span>): <span class="hljs-built_in">string</span> {
  <span class="hljs-keyword">const</span> tempDiv = <span class="hljs-variable language_">document</span>.<span class="hljs-title function_">createElement</span>(<span class="hljs-string">''div''</span>);
  tempDiv.<span class="hljs-property">innerHTML</span> = htmlContent;
  <span class="hljs-variable language_">console</span>.<span class="hljs-title function_">log</span>(tempDiv);

  <span class="hljs-keyword">const</span> codeBlocks = tempDiv.<span class="hljs-title function_">querySelectorAll</span>(<span class="hljs-string">''pre[data-language="xml"]''</span>);
  codeBlocks.<span class="hljs-title function_">forEach</span>(<span class="hljs-function">(<span class="hljs-params">block</span>) =&gt;</span> {
    <span class="hljs-keyword">let</span> language = <span class="hljs-string">''xml''</span>;
    <span class="hljs-keyword">const</span> codeElement = <span class="hljs-variable language_">document</span>.<span class="hljs-title function_">createElement</span>(<span class="hljs-string">''code''</span>);
    codeElement.<span class="hljs-property">className</span> = language;
    codeElement.<span class="hljs-property">innerHTML</span> = hljs.<span class="hljs-title function_">highlight</span>(block.<span class="hljs-property">textContent</span> || <span class="hljs-string">''''</span>, { language }).<span class="hljs-property">value</span>;
    block.<span class="hljs-property">innerHTML</span> = <span class="hljs-string">''''</span>;
    block.<span class="hljs-title function_">appendChild</span>(codeElement);
  });

  <span class="hljs-keyword">const</span> codeBlocksTS = tempDiv.<span class="hljs-title function_">querySelectorAll</span>(<span class="hljs-string">''pre[data-language="typescript"]''</span>);
  codeBlocksTS.<span class="hljs-title function_">forEach</span>(<span class="hljs-function">(<span class="hljs-params">block</span>) =&gt;</span> {
    <span class="hljs-keyword">let</span> language = <span class="hljs-string">''typescript''</span>;
    <span class="hljs-keyword">const</span> codeElement = <span class="hljs-variable language_">document</span>.<span class="hljs-title function_">createElement</span>(<span class="hljs-string">''code''</span>);
    codeElement.<span class="hljs-property">className</span> = language;
    codeElement.<span class="hljs-property">innerHTML</span> = hljs.<span class="hljs-title function_">highlight</span>(block.<span class="hljs-property">textContent</span> || <span class="hljs-string">''''</span>, { language }).<span class="hljs-property">value</span>;
    block.<span class="hljs-property">innerHTML</span> = <span class="hljs-string">''''</span>;
    block.<span class="hljs-title function_">appendChild</span>(codeElement);
  });

  <span class="hljs-keyword">return</span> tempDiv.<span class="hljs-property">innerHTML</span>;
}

</code></pre><div>I think It''ll pump up performance a little bit!</div><div></div><h3 class="ql-align-center">Insert &lt;img&gt; tag retake</h3><div>As you probably already seen, mostly each tutorial, etc. is super smooth; you read it or watch it and fill kind of dumb. Programmer just happy coding solution, but not here XD.</div><div>I''m not coding and writing it at one time, so I had time to reconsider my solution; it''s not perfect but it''s fit as hell. I''m just putting image at end of Control, and even if I need to move my image, I can just copy it as soon as it is visible in the Quill editor.</div><div></div><pre data-language="typescript"><code class="typescript">  <span class="hljs-title function_">insertImage</span>(<span class="hljs-params"></span>) {
    <span class="hljs-keyword">const</span> <span class="hljs-attr">modalConfig</span>: <span class="hljs-title class_">ModalConfig</span> = {
      <span class="hljs-attr">title</span>: <span class="hljs-string">''Add Image''</span>,
      <span class="hljs-attr">primaryButton</span>: <span class="hljs-string">''Insert''</span>,
      <span class="hljs-attr">secondaryButton</span>: <span class="hljs-string">''Cancel''</span>,
    }
    <span class="hljs-variable language_">this</span>.<span class="hljs-property">range</span> = <span class="hljs-variable language_">this</span>.<span class="hljs-title function_">quill</span>().<span class="hljs-property">quillEditor</span>.<span class="hljs-title function_">getSelection</span>();
    <span class="hljs-variable language_">this</span>.<span class="hljs-property">dialogService</span>.<span class="hljs-property">openDialog</span>&lt;<span class="hljs-title class_">AddImageComponent</span>&gt;
      (<span class="hljs-variable language_">this</span>.<span class="hljs-property">viewContainerRef</span>, modalConfig, <span class="hljs-title class_">AddImageComponent</span>).<span class="hljs-title function_">subscribe</span>(<span class="hljs-function">(<span class="hljs-params">modalStatus</span>) =&gt;</span> {
        <span class="hljs-keyword">if</span> (modalStatus.<span class="hljs-property">data</span>) {
          <span class="hljs-keyword">const</span> imgTag = <span class="hljs-string">`&lt;img src="<span class="hljs-subst">${modalStatus.data.form.controls.src.value}</span>" alt="<span class="hljs-subst">${modalStatus.data.form.controls.alt.value}</span>" style="max-width: 100%;"&gt;`</span>;
          <span class="hljs-keyword">if</span> (<span class="hljs-variable language_">this</span>.<span class="hljs-property">range</span>) {
            <span class="hljs-keyword">const</span> newValue = <span class="hljs-variable language_">this</span>.<span class="hljs-title function_">insertString</span>(<span class="hljs-variable language_">this</span>.<span class="hljs-property">blogForm</span>.<span class="hljs-property">controls</span>.<span class="hljs-property">content</span>.<span class="hljs-property">value</span> <span class="hljs-keyword">as</span> <span class="hljs-built_in">string</span>, <span class="hljs-variable language_">this</span>.<span class="hljs-property">blogForm</span>.<span class="hljs-property">controls</span>.<span class="hljs-property">content</span>.<span class="hljs-property">value</span>.<span class="hljs-title function_">toString</span>().<span class="hljs-property">length</span>, imgTag);
            <span class="hljs-variable language_">this</span>.<span class="hljs-property">blogForm</span>.<span class="hljs-property">controls</span>.<span class="hljs-property">content</span>.<span class="hljs-title function_">setValue</span>(newValue);
          }
        }
      });
  }

  <span class="hljs-title function_">insertString</span>(<span class="hljs-attr">originalString</span>: <span class="hljs-built_in">string</span>, <span class="hljs-attr">index</span>: <span class="hljs-built_in">number</span>, <span class="hljs-attr">stringToInsert</span>: <span class="hljs-built_in">string</span>): <span class="hljs-built_in">string</span> {
    <span class="hljs-keyword">const</span> result = [
      ...originalString.<span class="hljs-title function_">slice</span>(<span class="hljs-number">0</span>, index),
      ...stringToInsert,
      ...originalString.<span class="hljs-title function_">slice</span>(index),
    ].<span class="hljs-title function_">join</span>(<span class="hljs-string">''''</span>);
    <span class="hljs-keyword">return</span> result;
  }
</code></pre><h3 class="ql-align-center">Results!</h3><div>Oh, it''s not working xD</div><div>Angular, out of the box I only serve images from public directory; we need to force it to search also inside and as deep as it''s needed, so little fix:</div><div>Form:</div><div class="ql-align-center"></div><pre data-language="typescript"><code class="typescript"><span class="hljs-string">"assets"</span>: [
 {
   <span class="hljs-string">"glob"</span>: <span class="hljs-string">"**/*"</span>,
   <span class="hljs-string">"input"</span>: <span class="hljs-string">"public"</span>
 }
],
</code></pre><div>To:</div><pre data-language="typescript"><code class="typescript"><span class="hljs-string">"assets"</span>: [
  {
    <span class="hljs-string">"glob"</span>: <span class="hljs-string">"**/**"</span>,
    <span class="hljs-string">"input"</span>: <span class="hljs-string">"public"</span>
  }
],
</code></pre><div></div><div>Tada, you can see image right here; also, you can check the <strong>alt</strong></div><div class="ql-align-center"></div><div><img src="3.5/strong-typed-controlls.webp" alt="strong typed controls"></div>', false, '2024-10-20T18:50:24+00:00', 'https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/covers/ChatGPT%20Image%2011%20sie%202026,%2020_53_29.png', '[]'::jsonb),
  ('9468a494-0197-420a-bea1-fa7bfe16d2fb', 'a3b3cf93-6956-41c7-bec0-13f95dd42f26', 'Super performant Blog App in Angular 19 with SSG SSR and Hydration Part 5: Supbase migration and SignalStore intro!', 'Just migrated my Angular app from Firestore to Supabase—turned out pretty smooth overall, minus some classic SSR headaches and minor Supabase quirks. Got tables and RLS set up nicely, integrated some NGRX SignalStore action, and even managed environment secrets cleanly with GitHub Actions. Life isn’t always easy, but hey, at least the database looks clean now!', '<div>Hello.</div><div>Code on the public repo should be available here:</div><div><a href="https://github.com/Lukecsharpwalker/angularBlog" rel="noopener noreferrer" target="_blank">Git</a></div><div>I tried to move my envs to GitHub Actions but had some issues with the build, and this needs to wait.</div><div>At the bottom is a little errata because Supabase is not working with SSG/SSR as expected.</div><div></div><h2 class="ql-align-center">Creating new Supabase project</h2><div>It is not my first Supabase project, so we''ll skip creating a new account. It is quite easy and can be done by a 3rd-party provider.</div><div></div><h3 class="ql-align-center">Create DB and tables</h3><div>Just in case, Supabase provide tutorial for migrating form Firestore to Supabase</div><pre data-language="plain"><code class="javascript"><span class="hljs-attr">https</span>:<span class="hljs-comment">//supabase.com/docs/guides/platform/migrating-to-supabase/firestore-data</span>
</code></pre><div>In our case, we have only two collections; one is for creating SSG XD. So we got one; there is no point to struggling with some scripts. They never work on the happy path.</div><div>SQL is one of the best programming languages; it''s mature and intuitive, and there are a lot of good learning materials and examples. So LLMs are fed by good data so we can rely on them and use AI as leverage.</div><pre data-language="plain"><code class="javascript">-- <span class="hljs-title class_">Enable</span> required extensions
create extension <span class="hljs-keyword">if</span> not exists <span class="hljs-string">"uuid-ossp"</span>;


create table <span class="hljs-title function_">profiles</span> (
  id uuid primary key references auth.<span class="hljs-title function_">users</span>(id) on <span class="hljs-keyword">delete</span> cascade,
  username text unique not <span class="hljs-literal">null</span>,
  avatar_url text,
  created_at timestamp <span class="hljs-keyword">with</span> time zone <span class="hljs-keyword">default</span> <span class="hljs-title function_">now</span>()
);


create table <span class="hljs-title function_">tags</span> (
  id serial primary key,
  name text unique not <span class="hljs-literal">null</span>,
  color text not <span class="hljs-literal">null</span>,
  icon text not <span class="hljs-literal">null</span>
);


create table <span class="hljs-title function_">posts</span> (
  id uuid primary key <span class="hljs-keyword">default</span> <span class="hljs-title function_">uuid_generate_v4</span>(),
  user_id uuid references <span class="hljs-title function_">profiles</span>(id) on <span class="hljs-keyword">delete</span> cascade,
  title text not <span class="hljs-literal">null</span>,
  description text,
  content text,
  is_draft boolean <span class="hljs-keyword">default</span> <span class="hljs-literal">false</span>,
  created_at timestamp <span class="hljs-keyword">with</span> time zone <span class="hljs-keyword">default</span> <span class="hljs-title function_">now</span>()
);


create table <span class="hljs-title function_">comments</span> (
  id uuid primary key <span class="hljs-keyword">default</span> <span class="hljs-title function_">uuid_generate_v4</span>(),
  post_id uuid references <span class="hljs-title function_">posts</span>(id) on <span class="hljs-keyword">delete</span> cascade,
  user_id uuid references <span class="hljs-title function_">profiles</span>(id) on <span class="hljs-keyword">delete</span> cascade,
  content text,
  is_deleted boolean <span class="hljs-keyword">default</span> <span class="hljs-literal">false</span>,
  is_reported boolean <span class="hljs-keyword">default</span> <span class="hljs-literal">false</span>,
  created_at timestamp <span class="hljs-keyword">with</span> time zone <span class="hljs-keyword">default</span> <span class="hljs-title function_">now</span>()
);


create table <span class="hljs-title function_">post_tags</span> (
  post_id uuid references <span class="hljs-title function_">posts</span>(id) on <span class="hljs-keyword">delete</span> cascade,
  tag_id int references <span class="hljs-title function_">tags</span>(id) on <span class="hljs-keyword">delete</span> cascade,
  primary <span class="hljs-title function_">key</span> (post_id, tag_id)
);
</code></pre><div>Let''s try it.</div><pre data-language="plain"><code class="javascript"><span class="hljs-title class_">Success</span>. <span class="hljs-title class_">No</span> rows returned
<span class="hljs-title class_">Success</span>. <span class="hljs-title class_">No</span> rows returned
</code></pre><div>Double success!</div><div class="ql-align-center"><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//Xnapper-2025-04-21-10.16.39.jpg" alt="supabase-visualizer"></div><div>The table looks nice! Now we have more tables than we had documents. For me, it looks a lot cleaner! Some nullable tables should be not nullable.</div><div>The issue here is that when a new user creates an account, it''ll not be bound with the Profiles table. We, of course, can achieve that with some triggers on DB, or in this case, in the code.</div><div>I have only a few posts now, so the best option is to just copy data. I hate manual work, but sometimes it is the fastest way.</div><div></div><h3 class="ql-align-center">Setting up admin</h3><div>As you may remember, at Firestore we need to set the admin role. It was quite a struggle because we needed to create a function for that. Supabase is better because we can manipulate the DB directly from the GUI.</div><div class="ql-align-center"><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//addUser.jpg"></div><div class="ql-align-center"></div><div class="ql-align-center">In the raw information about the user, we can see roles, etc. Now the user has only the authenticated role.</div><div class="ql-align-center"><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//Xnapper-2025-04-22-10.20.26.jpg" alt="user details"></div><div>Now let run SQL command</div><pre data-language="xml"><code class="javascript">update auth.<span class="hljs-property">users</span>
set raw_app_meta_data = <span class="hljs-title function_">jsonb_set</span>(raw_app_meta_data, <span class="hljs-string">''{role}''</span>, <span class="hljs-string">''"Admin"''</span>, <span class="hljs-literal">true</span>),
    updated_at = <span class="hljs-title function_">now</span>()
where id = <span class="hljs-string">''User Id''</span>;
</code></pre><div>And here we have the admin role; it should work as a role in the JS SDK, and we will try it later.</div><div class="ql-align-center"><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//admin.jpg.jpg" alt="admin role"></div><div></div><div>Ok, let''s set RLS:</div><pre data-language="plain"><code class="sql"><span class="hljs-comment">-- ENABLE RLS ON TABLES</span>
<span class="hljs-keyword">alter table</span> profiles enable <span class="hljs-type">row</span> level security;
<span class="hljs-keyword">alter table</span> comments enable <span class="hljs-type">row</span> level security;
<span class="hljs-keyword">alter table</span> posts enable <span class="hljs-type">row</span> level security;

<span class="hljs-comment">-- RLS FOR PROFILES</span>
<span class="hljs-keyword">UPDATE</span>, <span class="hljs-keyword">DELETE</span>: <span class="hljs-keyword">by</span> profile owner <span class="hljs-keyword">or</span> Admin

<span class="hljs-keyword">create</span> policy "Users can edit their own profile or Admin"
<span class="hljs-keyword">on</span> profiles <span class="hljs-keyword">for</span> <span class="hljs-keyword">update</span>
<span class="hljs-keyword">using</span> (auth.uid() <span class="hljs-operator">=</span> id <span class="hljs-keyword">or</span> auth.jwt()<span class="hljs-operator">-</span><span class="hljs-operator">&gt;&gt;</span><span class="hljs-string">''role''</span> <span class="hljs-operator">=</span> <span class="hljs-string">''Admin''</span>);

<span class="hljs-keyword">create</span> policy "Users can delete their own profile or Admin"
<span class="hljs-keyword">on</span> profiles <span class="hljs-keyword">for</span> <span class="hljs-keyword">delete</span>
<span class="hljs-keyword">using</span> (auth.uid() <span class="hljs-operator">=</span> id <span class="hljs-keyword">or</span> auth.jwt()<span class="hljs-operator">-</span><span class="hljs-operator">&gt;&gt;</span><span class="hljs-string">''role''</span> <span class="hljs-operator">=</span> <span class="hljs-string">''Admin''</span>);

<span class="hljs-comment">-- INSERT: only authenticated users</span>
<span class="hljs-keyword">create</span> policy "Authenticated users can create profiles"
<span class="hljs-keyword">on</span> profiles <span class="hljs-keyword">for</span> <span class="hljs-keyword">insert</span>
<span class="hljs-keyword">with</span> <span class="hljs-keyword">check</span> (auth.role() <span class="hljs-operator">=</span> <span class="hljs-string">''authenticated''</span>);

<span class="hljs-comment">-- RLS FOR COMMENTS</span>
<span class="hljs-comment">-- SELECT: everyone (no restrictions)</span>
<span class="hljs-keyword">create</span> policy "Public can read comments"
<span class="hljs-keyword">on</span> comments <span class="hljs-keyword">for</span> <span class="hljs-keyword">select</span>
<span class="hljs-keyword">using</span> (<span class="hljs-literal">true</span>);

<span class="hljs-comment">-- INSERT: only authenticated users</span>
<span class="hljs-keyword">create</span> policy "Authenticated users can add comments"
<span class="hljs-keyword">on</span> comments <span class="hljs-keyword">for</span> <span class="hljs-keyword">insert</span>
<span class="hljs-keyword">with</span> <span class="hljs-keyword">check</span> (auth.role() <span class="hljs-operator">=</span> <span class="hljs-string">''authenticated''</span>);

<span class="hljs-comment">-- DELETE: Admin only</span>
<span class="hljs-keyword">create</span> policy "Only Admin can delete comments"
<span class="hljs-keyword">on</span> comments <span class="hljs-keyword">for</span> <span class="hljs-keyword">delete</span>
<span class="hljs-keyword">using</span> (auth.jwt()<span class="hljs-operator">-</span><span class="hljs-operator">&gt;&gt;</span><span class="hljs-string">''role''</span> <span class="hljs-operator">=</span> <span class="hljs-string">''Admin''</span>);

<span class="hljs-comment">-- RLS FOR POSTS</span>
<span class="hljs-comment">-- SELECT: everyone</span>
<span class="hljs-keyword">create</span> policy "Public can read posts"
<span class="hljs-keyword">on</span> posts <span class="hljs-keyword">for</span> <span class="hljs-keyword">select</span>
<span class="hljs-keyword">using</span> (<span class="hljs-literal">true</span>);

<span class="hljs-comment">-- INSERT, UPDATE, DELETE: Admin only</span>
<span class="hljs-keyword">create</span> policy "Only Admin can create posts"
<span class="hljs-keyword">on</span> posts <span class="hljs-keyword">for</span> <span class="hljs-keyword">insert</span>
<span class="hljs-keyword">with</span> <span class="hljs-keyword">check</span> (auth.jwt()<span class="hljs-operator">-</span><span class="hljs-operator">&gt;&gt;</span><span class="hljs-string">''role''</span> <span class="hljs-operator">=</span> <span class="hljs-string">''Admin''</span>);

<span class="hljs-keyword">create</span> policy "Only Admin can edit posts"
<span class="hljs-keyword">on</span> posts <span class="hljs-keyword">for</span> <span class="hljs-keyword">update</span>
<span class="hljs-keyword">using</span> (auth.jwt()<span class="hljs-operator">-</span><span class="hljs-operator">&gt;&gt;</span><span class="hljs-string">''role''</span> <span class="hljs-operator">=</span> <span class="hljs-string">''Admin''</span>);

<span class="hljs-keyword">create</span> policy "Only Admin can delete posts"
<span class="hljs-keyword">on</span> posts <span class="hljs-keyword">for</span> <span class="hljs-keyword">delete</span>
<span class="hljs-keyword">using</span> (auth.jwt()<span class="hljs-operator">-</span><span class="hljs-operator">&gt;&gt;</span><span class="hljs-string">''role''</span> <span class="hljs-operator">=</span> <span class="hljs-string">''Admin''</span>);
</code></pre><div>I think we can get rid of the Select Policy for Profile. It''s my mistake.</div><div></div><div class="ql-align-center"><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//description.jpg" alt="RLS explain"></div><pre data-language="plain"><code class="javascript"><span class="hljs-title class_">Success</span>. <span class="hljs-title class_">No</span> rows returned
</code></pre><div>Meanwhile, I''ll manually copy data and set tags, which are not set yet on the current version, and we''ll jump to code!</div><div></div><h2 class="ql-align-center">Setup and use Supabase</h2><div>Installing is easy as always:</div><pre data-language="plain"><code class="javascript">npm install @supabase/supabase-js
</code></pre><div></div><div>In the env file:</div><pre data-language="plain"><code class="javascript"><span class="hljs-keyword">export</span> <span class="hljs-keyword">const</span> environment = {
  <span class="hljs-attr">production</span>: <span class="hljs-literal">false</span>,
  <span class="hljs-attr">supabaseUrl</span>: <span class="hljs-string">''YOUR_SUPABASE_URL''</span>,
  <span class="hljs-attr">supabaseKey</span>: <span class="hljs-string">''YOUR_SUPABASE_KEY''</span>,
}
</code></pre><div></div><div>In the Supabase docs we have a great service example, but we will tweak it a little bit:</div><pre data-language="typescript"><code class="typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Injectable</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">''@angular/core''</span>;
<span class="hljs-keyword">import</span> {
  <span class="hljs-title class_">AuthChangeEvent</span>,
  <span class="hljs-title class_">AuthSession</span>,
  createClient,
  <span class="hljs-title class_">Provider</span>,
  <span class="hljs-title class_">Session</span>,
  <span class="hljs-title class_">SupabaseClient</span>,
} <span class="hljs-keyword">from</span> <span class="hljs-string">''@supabase/supabase-js''</span>;
<span class="hljs-keyword">import</span> { environment } <span class="hljs-keyword">from</span> <span class="hljs-string">''../../environments/environment''</span>;

<span class="hljs-meta">@Injectable</span>({
  <span class="hljs-attr">providedIn</span>: <span class="hljs-string">''root''</span>,
})
<span class="hljs-keyword">export</span> <span class="hljs-keyword">class</span> <span class="hljs-title class_">SupabaseService</span> {
  <span class="hljs-keyword">private</span> <span class="hljs-keyword">readonly</span> <span class="hljs-attr">supabase</span>: <span class="hljs-title class_">SupabaseClient</span>;
  <span class="hljs-keyword">public</span> <span class="hljs-attr">session</span>: <span class="hljs-title class_">AuthSession</span> | <span class="hljs-literal">null</span> = <span class="hljs-literal">null</span>;

  <span class="hljs-title function_">constructor</span>(<span class="hljs-params"></span>) {
    <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span> = <span class="hljs-title function_">createClient</span>(
      environment.<span class="hljs-property">supabaseUrl</span>,
      environment.<span class="hljs-property">supabaseKey</span>,
    );
  }

  <span class="hljs-title function_">getSession</span>(): <span class="hljs-title class_">AuthSession</span> | <span class="hljs-literal">null</span> {
    <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span>.<span class="hljs-property">auth</span>.<span class="hljs-title function_">getSession</span>().<span class="hljs-title function_">then</span>(<span class="hljs-function">(<span class="hljs-params">{ data }</span>) =&gt;</span> {
      <span class="hljs-variable language_">this</span>.<span class="hljs-property">session</span> = data.<span class="hljs-property">session</span>;
    });
    <span class="hljs-keyword">return</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">session</span>;
  }

  <span class="hljs-title function_">authChanges</span>(<span class="hljs-params">
    <span class="hljs-attr">callback</span>: (event: AuthChangeEvent, session: Session | <span class="hljs-literal">null</span>) =&gt; <span class="hljs-built_in">void</span>,
  </span>) {
    <span class="hljs-keyword">return</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span>.<span class="hljs-property">auth</span>.<span class="hljs-title function_">onAuthStateChange</span>(callback);
  }

  <span class="hljs-title function_">getClient</span>(): <span class="hljs-title class_">SupabaseClient</span> {
    <span class="hljs-keyword">return</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span>;
  }

  <span class="hljs-title function_">signInWithEmail</span>(<span class="hljs-params"><span class="hljs-attr">email</span>: <span class="hljs-built_in">string</span></span>) {
    <span class="hljs-keyword">return</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span>.<span class="hljs-property">auth</span>.<span class="hljs-title function_">signInWithOtp</span>({ email });
  }

  <span class="hljs-title function_">signInWithPassword</span>(<span class="hljs-params"><span class="hljs-attr">email</span>: <span class="hljs-built_in">string</span>, <span class="hljs-attr">password</span>: <span class="hljs-built_in">string</span></span>) {
    <span class="hljs-keyword">return</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span>.<span class="hljs-property">auth</span>.<span class="hljs-title function_">signInWithPassword</span>({ email, password });
  }

  <span class="hljs-title function_">signUp</span>(<span class="hljs-params"><span class="hljs-attr">email</span>: <span class="hljs-built_in">string</span>, <span class="hljs-attr">password</span>: <span class="hljs-built_in">string</span></span>) {
    <span class="hljs-keyword">return</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span>.<span class="hljs-property">auth</span>.<span class="hljs-title function_">signUp</span>({ email, password });
  }

  <span class="hljs-title function_">signInWithProvider</span>(<span class="hljs-params"><span class="hljs-attr">provider</span>: <span class="hljs-title class_">Provider</span></span>) {
    <span class="hljs-keyword">return</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span>.<span class="hljs-property">auth</span>.<span class="hljs-title function_">signInWithOAuth</span>({
      provider,
      <span class="hljs-attr">options</span>: {
        <span class="hljs-attr">redirectTo</span>: <span class="hljs-variable language_">window</span>.<span class="hljs-property">location</span>.<span class="hljs-property">origin</span>,
      },
    });
  }

  <span class="hljs-title function_">signOut</span>(<span class="hljs-params"></span>) {
    <span class="hljs-keyword">return</span> <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span>.<span class="hljs-property">auth</span>.<span class="hljs-title function_">signOut</span>();
  }
}

</code></pre><div></div><div>Ok, now we can initialize it:</div><pre data-language="plain"><code class="javascript">{
  <span class="hljs-attr">provide</span>: <span class="hljs-variable constant_">APP_INITIALIZER</span>,
  <span class="hljs-attr">useFactory</span>: supabaseInitializer,
  <span class="hljs-attr">deps</span>: [<span class="hljs-title class_">SupabaseService</span>],
  <span class="hljs-attr">multi</span>: <span class="hljs-literal">true</span>,
}
</code></pre><div><strong>APP_INITIALIZER</strong> is deprecated, but we can still use it!</div><div></div><div>and the initializer code:</div><pre data-language="typescript"><code class="typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">SupabaseService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">''../services/supabase.service''</span>;
<span class="hljs-keyword">import</span> { <span class="hljs-title class_">Subscription</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">''@supabase/supabase-js''</span>;

<span class="hljs-keyword">export</span> <span class="hljs-keyword">function</span> <span class="hljs-title function_">supabaseInitializer</span>(<span class="hljs-params">
  <span class="hljs-attr">supabase</span>: <span class="hljs-title class_">SupabaseService</span>,
</span>): <span class="hljs-function">() =&gt;</span> { <span class="hljs-attr">data</span>: { <span class="hljs-attr">subscription</span>: <span class="hljs-title class_">Subscription</span> } } {
  <span class="hljs-keyword">return</span> <span class="hljs-function">() =&gt;</span>
    supabase.<span class="hljs-title function_">authChanges</span>(<span class="hljs-function">(<span class="hljs-params">_, session</span>) =&gt;</span> (supabase.<span class="hljs-property">session</span> = session));
}

</code></pre><div></div><div>Quick test, and it fails. I had some issues with SSR, so I disabled it on dev for now. Hope that connecting to the DB will help!</div><div></div><h3>Create (or not) Interfaces</h3><div>Supabase has another great feature: it creates interfaces for us!</div><pre data-language="plain"><code class="javascript">npm install supabase --save-dev
npx supabase gen types typescript --project-id aqdbdmepncxxuanlymwr &gt; src/app/supabase-types.<span class="hljs-property">ts</span>
</code></pre><h3></h3><div class="ql-align-center"><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//wtf.jpg " alt="Database schema"></div><div></div><div>WTF?! Yeah, not perfect, but let''s bring some magic to life. IntelliJ provides some free credits each month!</div><div></div><div class="ql-align-center"><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//magic.jpg" alt="AI magic "></div><div></div><div>Much better!</div><div class="ql-align-center"><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//better.jpg" alt="types"></div><div></div><div>Our call will look like this:</div><pre data-language="javascript"><code class="sql"> async getPosts(): Promise<span class="hljs-operator">&lt;</span>PostRow[] <span class="hljs-operator">|</span> <span class="hljs-keyword">null</span><span class="hljs-operator">&gt;</span> {
    let { data: posts } <span class="hljs-operator">=</span> await this.supabaseService.getClient
      .<span class="hljs-keyword">from</span>(<span class="hljs-string">''posts''</span>)
      .<span class="hljs-keyword">select</span>(<span class="hljs-string">''*''</span>)
      .<span class="hljs-keyword">order</span>(<span class="hljs-string">''created_at''</span>, { ascending: <span class="hljs-literal">false</span> });

    <span class="hljs-keyword">return</span> posts;
  }
</code></pre><div>Of course we will need to add a relation later.</div><h2 class="ql-align-center"><img src="">Install NGRX SignalStore</h2><pre data-language="plain"><code class="javascript">ng add @ngrx/signals@latest
</code></pre><div>Lets create a store file <strong>posts.store.ts</strong></div><div></div><pre data-language="typescript"><code class="typescript"><span class="hljs-keyword">import</span> { <span class="hljs-title class_">Post</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">''../../../../types/supabase''</span>;
<span class="hljs-keyword">import</span> {
  patchState,
  signalStore,
  withMethods,
  withState,
} <span class="hljs-keyword">from</span> <span class="hljs-string">''@ngrx/signals''</span>;
<span class="hljs-keyword">import</span> { inject } <span class="hljs-keyword">from</span> <span class="hljs-string">''@angular/core''</span>;
<span class="hljs-keyword">import</span> { <span class="hljs-title class_">ReaderApiService</span> } <span class="hljs-keyword">from</span> <span class="hljs-string">''../../../_services/reader-api.service''</span>;

<span class="hljs-keyword">type</span> <span class="hljs-title class_">PostsState</span> = {
  <span class="hljs-attr">posts</span>: <span class="hljs-title class_">Post</span>[];
  <span class="hljs-attr">loading</span>: <span class="hljs-built_in">boolean</span>;
  <span class="hljs-attr">error</span>: <span class="hljs-built_in">string</span> | <span class="hljs-literal">null</span>;
};

<span class="hljs-keyword">const</span> <span class="hljs-attr">initialState</span>: <span class="hljs-title class_">PostsState</span> = {
  <span class="hljs-attr">posts</span>: [],
  <span class="hljs-attr">loading</span>: <span class="hljs-literal">false</span>,
  <span class="hljs-attr">error</span>: <span class="hljs-literal">null</span>,
};

<span class="hljs-keyword">export</span> <span class="hljs-keyword">const</span> <span class="hljs-title class_">PostsStore</span> = <span class="hljs-title function_">signalStore</span>(
  { <span class="hljs-attr">providedIn</span>: <span class="hljs-string">''root''</span> },
  <span class="hljs-title function_">withState</span>(initialState),

  <span class="hljs-title function_">withMethods</span>(<span class="hljs-function">(<span class="hljs-params">state, postService = inject(ReaderApiService)</span>) =&gt;</span> ({
    <span class="hljs-keyword">async</span> <span class="hljs-title function_">getPosts</span>(<span class="hljs-params"></span>) {
      <span class="hljs-title function_">patchState</span>(state, { <span class="hljs-attr">loading</span>: <span class="hljs-literal">true</span>, <span class="hljs-attr">error</span>: <span class="hljs-literal">null</span> });
      <span class="hljs-keyword">try</span> {
        <span class="hljs-keyword">const</span> posts = <span class="hljs-keyword">await</span> postService.<span class="hljs-title function_">getPosts</span>();
        <span class="hljs-keyword">if</span> (posts) {
          <span class="hljs-title function_">patchState</span>(state, { posts, <span class="hljs-attr">loading</span>: <span class="hljs-literal">false</span> });
        } <span class="hljs-keyword">else</span> {
          <span class="hljs-title function_">patchState</span>(state, { <span class="hljs-attr">error</span>: <span class="hljs-string">''No posts found''</span>, <span class="hljs-attr">loading</span>: <span class="hljs-literal">false</span> });
        }
      } <span class="hljs-keyword">catch</span> (error) {
        <span class="hljs-title function_">patchState</span>(state, { <span class="hljs-attr">error</span>: <span class="hljs-string">''Failed to fetch posts''</span>, <span class="hljs-attr">loading</span>: <span class="hljs-literal">false</span> });
      }
    },
  })),
  <span class="hljs-title function_">withHooks</span>({
    <span class="hljs-title function_">onInit</span>(<span class="hljs-params">store</span>) {
      store.<span class="hljs-title function_">getPosts</span>();
    },
  }),
);
</code></pre><div>Remember the onInit hook; without this, you need to call it manually on init.</div><div></div><div>Usage is super simple:</div><pre data-language="plain"><code class="javascript">postStore = <span class="hljs-title function_">inject</span>(<span class="hljs-title class_">PostsStore</span>);
posts = <span class="hljs-variable language_">this</span>.<span class="hljs-property">postStore</span>.<span class="hljs-property">posts</span>;
</code></pre><div></div><pre data-language="xml"><code class="xml"><span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"flex justify-center mt-5"</span>&gt;</span>
  <span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"w-full"</span>&gt;</span>
    <span class="hljs-tag">&lt;<span class="hljs-name">div</span> <span class="hljs-attr">class</span>=<span class="hljs-string">"grid"</span>&gt;</span>
      @for (post of posts(); track post.id; let f = $first) {
        <span class="hljs-tag">&lt;<span class="hljs-name">app-post-card</span> [<span class="hljs-attr">post</span>]=<span class="hljs-string">"post"</span>&gt;</span><span class="hljs-tag">&lt;/<span class="hljs-name">app-post-card</span>&gt;</span>
      }
    <span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>
  <span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>
<span class="hljs-tag">&lt;/<span class="hljs-name">div</span>&gt;</span>
</code></pre><div></div><div>That''s all!</div><div class="ql-align-center"><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//thatall.jpg" alt="post list"></div><div></div><div>Ok, now let''s tweak query to get all data We need posts with author tags and also only posts that are not in the <strong>draft</strong>.</div><pre data-language="javascript"><code class="sql"> async getPosts(): Promise<span class="hljs-operator">&lt;</span>Post[] <span class="hljs-operator">|</span> <span class="hljs-keyword">null</span><span class="hljs-operator">&gt;</span> {
  const { data: posts } <span class="hljs-operator">=</span> await this.supabaseService.getClient
    .<span class="hljs-keyword">from</span>(<span class="hljs-string">''posts''</span>)
    .<span class="hljs-keyword">select</span>(`
    <span class="hljs-operator">*</span>,
    author:profiles ( id, username, avatar_url ),
    post_tags (
      tags ( id, name, color, icon )
  )
  `,
    )
    .eq(<span class="hljs-string">''is_draft''</span>, <span class="hljs-literal">false</span>)
    .<span class="hljs-keyword">order</span>(<span class="hljs-string">''created_at''</span>, { ascending: <span class="hljs-literal">false</span> });

  <span class="hljs-keyword">return</span> posts;
}
</code></pre><div>There was an issue with the author because <strong>Read</strong> was available for the auth user; this was a mistake.</div><div></div><div>Nice, it''s working. Now I''ll adjust all other places, and then we''ll check if issues with the SSR are gone!</div><div></div><div>They are not gone; to be honest, it was very hard to spot where the issue was. I''ve tried to cut all possibilities; everything and nothing helps, so the issue needs to be in the root.</div><div>I have found that Supabase got some glitch at init.</div><div></div><div>In the <strong>Supabase service,</strong> I changed the client creation:</div><pre data-language="plain"><code class="javascript"><span class="hljs-title function_">constructor</span>(<span class="hljs-params"></span>) {
  <span class="hljs-variable language_">this</span>.<span class="hljs-property">supabase</span> = <span class="hljs-variable language_">this</span>.<span class="hljs-property">ngZone</span>.<span class="hljs-title function_">runOutsideAngular</span>(<span class="hljs-function">() =&gt;</span>
    <span class="hljs-title function_">createClient</span>(environment.<span class="hljs-property">supabaseUrl</span>, environment.<span class="hljs-property">supabaseKey</span>),
  );
}
</code></pre><div>It helps to build and run an app, but the content didn''t prerender. XD WTF, mate, it''s supposed to be easy, just one time xD</div><div>I''m not sure if it''s Supabase issue or SignalStore issue but</div><pre data-language="javascript"><code class="javascript"><span class="hljs-built_in">setTimeout</span>(<span class="hljs-function">() =&gt;</span> {}, <span class="hljs-number">0</span>);
</code></pre><div>helps to prerender content. I will investigate this later because it''s a lame approach.</div><div></div><h2>Setup env on the GitHub Actions</h2><div>Yeah, I pushed envs, but there are add-ons for Git that revert whole history and remove specific files; it took less than a second, so fair enough for that kind of a mistake.</div><div>Keys will be exposed anyway in the bundle; it''s just how FE works, but we have a server app for our static file, and maybe it will be used for some password recovery, so admin credentials should be confidential!</div><div></div><div>I''ve added this step to jobs</div><pre data-language="plain"><code class="yaml"><span class="hljs-bullet">-</span> <span class="hljs-attr">name:</span> <span class="hljs-string">Generate</span> <span class="hljs-string">environment.ts</span> <span class="hljs-string">from</span> <span class="hljs-string">secrets</span>
        <span class="hljs-attr">shell:</span> <span class="hljs-string">bash</span>
        <span class="hljs-attr">run:</span> <span class="hljs-string">|
          cat &gt; src/environments/environment.ts &lt;&lt;''EOF''
          export const environment = {
            production: true,
            supabaseUrl: ''${{ secrets.SUPABASE_URL }}'',
            supabaseKey: ''${{ secrets.SUPABASE_ANON_KEY }}'',
          };
          EOF
</span>
      <span class="hljs-bullet">-</span> <span class="hljs-attr">run:</span> <span class="hljs-string">npm</span> <span class="hljs-string">ci</span>
      <span class="hljs-bullet">-</span> <span class="hljs-attr">run:</span> <span class="hljs-string">npm</span> <span class="hljs-string">run</span> <span class="hljs-string">test</span> <span class="hljs-string">--</span> <span class="hljs-string">--browsers=ChromeHeadless</span> <span class="hljs-string">--watch=false</span> <span class="hljs-string">--no-progress</span>
</code></pre><div></div><div>PR action passed! So that''s all; thank you! Have a lovely day!</div><div></div><h2 class="ql-align-center">Errata</h2><div>So Supabase is not working great for SSG/SSR.</div><div>There was an issue with initializing Supabase then; for prerender, I fixed prerender, but then, something went wrong with hydration:</div><div>https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/post-images//flicking.mov</div><div></div><h3 class="ql-align-center">Leveraging SSG by Supabase autogenerated Rest API</h3><div>Supabase has an autogenerated API; I''m quite sure that is handled by <strong>PostgREST. </strong></div><pre data-language="typescript"><code class="xml">  getPosts(): Observable&lt;Post[] | null&gt; {
    const selectQuery = `
      *,
      author:profiles(id,username,avatar_url),
      post_tags(tags(id,name,color,icon))
    `
      .replace(/\s+/g, '' '')
      .trim();

    const params = new HttpParams()
      .set(''select'', selectQuery)
      .set(''is_draft'', ''eq.false'')
      .set(''order'', ''created_at.desc'');

    const headers = new HttpHeaders({
      apikey: this.apiKey,
      Authorization: `Bearer ${this.apiKey}`,
      Accept: ''application/json'',
    });

    return this.http.get&lt;Post[]&gt;(`${this.baseUrl}posts`, { headers, params });
  }
</code></pre><div>Looks bad, works great - fair enough!.</div><div>It could be refactored and will be! For sure this <strong>Bearer</strong> should be in the interceptor.</div><div></div><div>Also, SignalStore should be adjusted.</div><pre data-language="typescript"><code class="xml">withMethods((store, postService = inject(ReaderApiService)) =&gt; ({
  getPost: rxMethod<span class="hljs-tag">&lt;<span class="hljs-name">string</span>&gt;</span>(
    pipe(
      tap(() =&gt; patchState(store, { loading: true, error: null })),
      switchMap((id) =&gt;
        postService.getPost(id).pipe(
          tapResponse({
            next: (post: Post) =&gt; patchState(store, { post, loading: false }),
            error: (err: string) =&gt;
              patchState(store, {
                error: err ?? ''Failed to fetch post'',
                loading: false,
              }),
          }),
        ),
      ),
    ),
  ),
})),
</code></pre><div><strong>rxMethod </strong>is provided by NGRX SignalStore and handles subscriptions inside. How cool is that?</div><div></div><div>Now SSG and SSR work like a charm!</div>', false, '2025-05-01T09:09:13+00:00', 'https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/covers/ChatGPT%20Image%2011%20sie%202026,%2020_53_29.png', '[]'::jsonb),
  ('c6ed64be-b609-48f1-b58d-2aa4e4b1abe5', 'a3b3cf93-6956-41c7-bec0-13f95dd42f26', 'Super performant Blog app in Angular 20 — Part X: No more boundaries', 'ok', '<h2 class="ql-align-center">Architecture goal</h2><div>What is a good architecture?</div><div>I’ve asked myself this question many times throughout my programming journey.</div><div>I still remember my first job as a junior .NET/C# developer. My first project was a web app built with .NET Core and Razor Pages. A colleague showed me the repository and—oh fuck—I thought, <em>what a mess</em>. The entire app was crammed into a single controller file with countless endpoints and logic mixed together. The file had around 20,000 lines of code (or even more it had about 7 features?). Miraculously, it was running in production. XD</div><div>I remember my first task: exporting data to Excel. I managed to finish it, but I wasted hours just trying to understand the codebase. I worked there for about a month XD. Then I landed a new job as a junior developer.</div><div>At the same time, I was building an app for my university finals. I was really proud of it—until one day, I showed it to a senior colleague. His eyes screamed: <em>“What is that shit?!”</em> I was confused. I built it by following a Udemy course with a 4.6/5 rating. It had to be good, right?</div><div>Yeah, of course XD. Everything for just $10—<em>occasionally</em> discounted from $599, 360 days in a year.</div><div>Just like in that messy repo from my first job, I also had all the logic in the controller and no service layer at all XD. That senior helped me clean up the architecture a bit, and later, the Udemy course was updated with an N-tier architecture. Progress!</div><div>Over time, the concept of architecture evolved in my head. It stopped being this mysterious, abstract idea and became something simple—just a clear separation of responsibilities, usually reflected in a folder structure.</div><div>Then came my first solo Angular project. No guidelines, just a tight deadline. The only thing I knew about Angular was that it was a competitor to React. Nothing more. Let the fun begin XD.</div><div>This time, I failed.</div><div>I was still a junior .NET developer, trying to apply my newfound architectural knowledge. I eventually moved on to another job. That project was almost complete—just a few bugs left. The customer was happy because it was only a demo, and they were already planning version 2, which they wanted us to build.</div><div>Sounds great, right? My first Angular app, mostly done solo, and the customer was satisfied.</div><div>But at the beginning, I said I failed—and I meant it.</div><div>My folder structure was a mess. Fast development, constant changes, shifting ideas. I wasn’t ready for this war. I wasted tons of time just navigating the folder tree.</div><div>So the goal is to create scalable architecture.</div><div>Now this blog app is quite a mess. Every fast-developed app suffers much more when the architecture is not correct.</div><div>I have some plans to expand my BlogAPP to include some kind of microservice. I want my posts to be pre-rendered, so I don''t want to pre-build includes too much data. One separate project will be a playground.</div><div>Architecture will look like this:</div><div>1) BlogApp with SSG and SSR,</div><div>2) Admin page as a casual Angular app, client-side rendered,</div><div>3) Playground app that will be used as an iframe or something like this; I need to dig into this topic.</div><div>4) Shared lib.</div><div></div><div class="ql-align-justify">Apps will have their own styles, etc. Now I have a mess on the Admin side:</div><div class="ql-align-justify"></div><div><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/public/part-6//admin.jpg" alt="admin-colors"></div><div></div><div>We''ll based on this <a href="https://angularexperts.io/products/ebook-angular-enterprise-architecture" rel="noopener noreferrer" target="_blank">book</a></div><div>It''s a great book; I''ve already implemented it in the production app, with some extra adjustments, but it passed an exam!</div><div></div><div>Here a little scope of the book, from the official <a href="https://angularexperts.io/products/ebook-angular-enterprise-architecture" rel="noopener noreferrer" target="_blank">site</a></div><ul><li><span style="color: rgb(71, 85, 105);">How to structure your Angular application to make it maintainable and extendable, and especially to preserve high velocity of development over time</span></li><li><span style="color: rgb(71, 85, 105);">How to set up automated tooling based architecture validation to ensure that your project stays maintainable and extendable over the whole project lifetime</span></li><li><span style="color: rgb(71, 85, 105);">How to separate your business features into isolated parts within the framework of the architecture and what are the benefits of doing so</span></li><li><span style="color: rgb(71, 85, 105);">How to share code between features in a maintainable way and what are the tradeoffs of doing so</span></li><li><span style="color: rgb(71, 85, 105);">How to set up your Angular workspace with tooling to support team collaboration</span></li><li><span style="color: rgb(71, 85, 105);">How to create standalone first Angular architecture and embrace new, better standalone APIs to make your project future proof</span></li></ul><div></div><div>The whole project needs to be recreated.</div><div>I wouldn''t provide screenshots from book, I think it''s not fair - if you want look deeper, just buy a book.</div><h2 class="ql-align-center">Recreate App</h2><div>As I mentioned, the whole app will be recreated—nothing should be left in the /src.</div><pre data-language="plaintext">ng generate application code-samples-mfe
ng generate application web
ng generate application admin
ng generate library
</pre><div>That''s it''s enough project for start.</div><div></div><div>I''ve created LLM files for my AI agents; today I will use the Claude Code. Some of my files are public in the repo, some private; the architecture file is private because for me it''s not fair to publish someone''s work.</div><div></div><div>OK, this is basically how the architecture should look:</div><div><img src="https://aqdbdmepncxxuanlymwr.supabase.co/storage/v1/object/sign/part-7/architecture.jpg.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV84MTViMGExMS00MGFhLTRjMWMtYTlhYS0xYjRhNDgwZmU4M2UiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJwYXJ0LTcvYXJjaGl0ZWN0dXJlLmpwZy5qcGciLCJpYXQiOjE3NTU1MzE3MTcsImV4cCI6MjA3MDg5MTcxN30.NpXwDR-Zqvcwt1AAuVwHmP7C62vYCIt1Gm1WI9NJsdI" alt="architecture"></div><div>CC created some subfolders with dummy features, etc., but they will be overridden.</div><div></div><div>The next step is to install and configure Prettier</div><pre data-language="xml"><code class="xml">{
  "semi": true,
  "trailingComma": "es5",
  "singleQuote": true,
  "printWidth": 100,
  "tabWidth": 2,
  "useTabs": false,
  "endOfLine": "lf",
  "bracketSpacing": true,
  "bracketSameLine": false,
  "arrowParens": "avoid",
  "overrides": [
    {
      "files": "*.html",
      "options": {
        "parser": "angular"
      }
    },
    {
      "files": "*.scss",
      "options": {
        "singleQuote": false
      }
    },
    {
      "files": "*.md",
      "options": {
        "proseWrap": "preserve"
      }
    }
  ]
}
</code></pre><div>and in the package.json</div><pre data-language="xml"><code class="xml">{
...
  "format": "prettier --write .",
  "format:check": "prettier --check .",
  "format:staged": "prettier --write",
...
}

</code></pre><div></div><div><strong>ESLint </strong>is another very helpful thing that I skipped during this project.</div><pre data-language="plain">ng lint
</pre><div>and all magic will happen automatically. Remember to fix the prefix for apps in the angular.json and the eslint config files.</div><div>I''ve done this, and now CC is fixing my issues with prefixes created by Angular out of the box.</div><div></div><div>And one of the key points of this article! Automated architecture validation with eslint-plugin-boundaries.</div><pre data-language="plain">npm i -D eslint-plugin-boundaries eslint-import-resolver-typescript
</pre><div></div><div>this is my full eslint.config.js</div><pre data-language="typescript"><code class="typescript"><span class="hljs-comment">// @ts-check</span>
<span class="hljs-keyword">const</span> eslint = <span class="hljs-built_in">require</span>(<span class="hljs-string">"@eslint/js"</span>);
<span class="hljs-keyword">const</span> tseslint = <span class="hljs-built_in">require</span>(<span class="hljs-string">"typescript-eslint"</span>);
<span class="hljs-keyword">const</span> angular = <span class="hljs-built_in">require</span>(<span class="hljs-string">"angular-eslint"</span>);
<span class="hljs-keyword">const</span> boundaries = <span class="hljs-built_in">require</span>(<span class="hljs-string">"eslint-plugin-boundaries"</span>);

<span class="hljs-variable language_">module</span>.<span class="hljs-property">exports</span> = tseslint.<span class="hljs-title function_">config</span>(
  {
    <span class="hljs-attr">ignores</span>: [
      <span class="hljs-string">"dist/**"</span>,
      <span class="hljs-string">"node_modules/**"</span>, 
      <span class="hljs-string">"coverage/**"</span>,
      <span class="hljs-string">".angular/**"</span>,
      <span class="hljs-string">"src/**"</span>, <span class="hljs-comment">// Exclude legacy monolith during migration</span>
      <span class="hljs-string">"**/*.spec.ts"</span>,
      <span class="hljs-string">"**/e2e/**"</span>,
      <span class="hljs-string">"**/*.generated.ts"</span>,
      <span class="hljs-string">"**/*.d.ts"</span>,
      <span class="hljs-string">"!**/*.spec.d.ts"</span>,
      <span class="hljs-string">"*.config.js"</span>,
      <span class="hljs-string">"*.config.ts"</span>
    ]
  },
  {
    <span class="hljs-attr">files</span>: [<span class="hljs-string">"**/*.ts"</span>],
    <span class="hljs-attr">extends</span>: [
      eslint.<span class="hljs-property">configs</span>.<span class="hljs-property">recommended</span>,
      ...tseslint.<span class="hljs-property">configs</span>.<span class="hljs-property">recommended</span>,
      ...tseslint.<span class="hljs-property">configs</span>.<span class="hljs-property">stylistic</span>,
      ...angular.<span class="hljs-property">configs</span>.<span class="hljs-property">tsRecommended</span>,
    ],
    <span class="hljs-attr">processor</span>: angular.<span class="hljs-property">processInlineTemplates</span>,
    <span class="hljs-attr">plugins</span>: {
      boundaries
    },
    <span class="hljs-attr">settings</span>: {
      <span class="hljs-string">"import/resolver"</span>: {
        <span class="hljs-string">"typescript"</span>: {
          <span class="hljs-string">"alwaysTryTypes"</span>: <span class="hljs-literal">true</span>
        }
      },
